<?php require_once '../includes/functions.php';require_login();$s=$pdo->prepare('SELECT p.* FROM favorites f JOIN places p ON p.id=f.place_id WHERE f.user_id=? ORDER BY f.created_at DESC');$s->execute([user()['id']]);$places=$s->fetchAll();$page_title='My Favorites';require '../includes/header.php';?><section class="section"><h1>My Favorites</h1><p class="muted">Your saved places.</p><div class="card-grid"><?php foreach($places as $p):?><a class="place-card" href="<?=url('place.php?slug='.urlencode($p['slug']))?>"><div class="place-image"><img src="<?=e(image_url($p['cover_image']))?>" alt=""></div><div class="place-info"><h3><?=e($p['name'])?></h3><p><?=e($p['district'])?></p></div></a><?php endforeach;?></div><?php if(!$places):?><div class="empty-state">No favorites yet. Explore destinations and save your favourites.</div><?php endif;?></section><?php require '../includes/footer.php';?>
